window.docContents[72].resolve({"/#Adic-Spaces-___-Lean-blueprint":{"contents":"This is the blueprint for the Adic-Spaces\nformalisation (Birkbeck) of Huber's theory of adic spaces — the point-set\nfoundations of -adic geometry and perfectoid spaces, following Wedhorn's\nAdic Spaces notes. It develops Huber rings and Tate rings, the valuation spectrum\n, continuous valuations, rings of integral elements, the adic spectrum\n, its rational subsets and analytic locus, Tate algebras, and (in\nprogress) the structure sheaf.\n\nEach node carries a (lean := …) reference to the actual declaration in the\n«Adic spaces» library, so Verso reads its completion status directly from Lean.\nThe dependency graph at the foot of the page records how the constructions build on\none another.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Adic Spaces — Lean blueprint","id":"/#Adic-Spaces-___-Lean-blueprint"}});